extern alias apiv5;
using System.Net;using System.Net.Http.Json;using System.Text.Json;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.Extensions.DependencyInjection;using Npgsql;using SanSo.Api.Modules;using Xunit;using V5Program=apiv5::Program;
namespace SanSo.Api.V5.Tests;
public sealed class PostgresInventoryHttpV5Tests
{
 [Fact]public async Task AuthenticatedConcurrentReserveReturnsOneSuccessOneConflict(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;var tenant=Guid.NewGuid();var product=Guid.NewGuid();var location=Guid.NewGuid();var sku=$"HTTP-LAST-{Guid.NewGuid():N}";await Seed(cs,tenant,product,location,sku);await using var factory=new WebApplicationFactory<V5Program>().WithWebHostBuilder(x=>{x.UseEnvironment("Development");x.UseSetting("ConnectionStrings:Postgres",cs);});using var client=factory.CreateClient();var identity=factory.Services.GetRequiredService<IdentityService>();var secret=IdentityService.GenerateTotpSecret();var email=$"inventory-{Guid.NewGuid():N}@example.invalid";var user=identity.Register(email,"Inventory Owner","Long-Safe-Inventory-Password-2026!",secret);identity.AddMembership(tenant.ToString(),user.Id,OrgRole.Owner);var login=await client.PostAsJsonAsync("/api/auth/login",new{email,password="Long-Safe-Inventory-Password-2026!",tenantId=tenant.ToString(),totpCode=IdentityService.CurrentTotp(secret)});var token=(await login.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("token").GetString()!;Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync($"/api/inventory/{sku}/reserve",new{quantity=1,sourceKey="anonymous"})).StatusCode);var responses=await Task.WhenAll(Post(client,$"/api/inventory/{sku}/reserve",new{quantity=1,sourceKey="http-a"},token,tenant),Post(client,$"/api/inventory/{sku}/reserve",new{quantity=1,sourceKey="http-b"},token,tenant));Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.OK);var conflict=Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.Conflict);Assert.Contains("INSUFFICIENT_ATP",await conflict.Content.ReadAsStringAsync());}
 static async Task<HttpResponseMessage> Post(HttpClient c,string path,object body,string token,Guid tenant){using var r=new HttpRequestMessage(HttpMethod.Post,path){Content=JsonContent.Create(body)};r.Headers.Authorization=new("Bearer",token);r.Headers.Add("X-Tenant-Id",tenant.ToString());return await c.SendAsync(r);}static async Task Seed(string cs,Guid tenant,Guid product,Guid location,string sku){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();foreach(var item in new[]{(Sql:"INSERT INTO organizations(id,slug,name) VALUES($1,$2,'HTTP inventory')",Args:new object[]{tenant,$"http-inventory-{tenant:N}"}),(Sql:"INSERT INTO products(id,organization_id,name,canonical_sku) VALUES($1,$2,'Last unit',$3)",Args:new object[]{product,tenant,sku}),(Sql:"INSERT INTO inventory_locations(id,organization_id,code,name) VALUES($1,$2,'MAIN','Main')",Args:new object[]{location,tenant}),(Sql:"INSERT INTO inventory_balances(organization_id,product_id,location_id,on_hand,reserved,quarantine) VALUES($1,$2,$3,1,0,0)",Args:new object[]{tenant,product,location})}){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=item.Sql;foreach(var value in item.Args)q.Parameters.AddWithValue(value);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}
}
